args.command:
for iban in IE29AIBK93115212345678 IE64HBPL93115298765432; do echo "$iban" | awk '{
  s=$0; t=substr(s,5) substr(s,1,4); n="";
  for(i=1;i<=length(t);i++){c=substr(t,i,1); if(c>="A"&&c<="Z"){n=n (index("ABCDEFGHIJKLMNOPQRSTUVWXYZ",c)+9)} else n=n c}
  r=0; for(i=1;i<=length(n);i++){ r=(r*10+substr(n,i,1))%97 }
  print s, (r==1 ? "VALID check digits" : "INVALID check digits");
}'; done

